        let temp = arr[j];
        arr[j] = arr[j + 1];
        arr[j + 1] = temp;
      }
    }
  }
  return arr;
}

console.log(bubbleSort([5, 2, 9, 1, 5, 6]));

function countLinear(n) {
  return n;
}

function countQuadratic(n) {
  return n * n;
}

for (const n of [10, 100, 1000]) {
  console.log(`n=${n}: linear=${countLinear(n)}, quadratic=${countQuadratic(n)}`);
}

interviewQuestions.answer:
Bubble sort repeatedly compares adjacent pairs and swaps them if they're out of order, making multiple passes until no swaps are needed. Tracing through `[5, 1, 4, 2]`:

**Pass 1:**
- Compare 5, 1 -> out of order, swap -> `[1, 5, 4, 2]`
- Compare 5, 4 -> out of order, swap -> `[1, 4, 5, 2]`
- Compare 5, 2 -> out of order, swap -> `[1, 4, 2, 5]`
(5 has now 'bubbled up' to its correct final position at the end.)

**Pass 2:**
- Compare 1, 4 -> already in order, no swap
- Compare 4, 2 -> out of order, swap -> `[1, 2, 4, 5]`
(4 is now in its correct position.)

**Pass 3:**
- Compare 1, 2 -> already in order, no swap
(No swaps occurred in this pass, so the array is fully sorted: `[1, 2, 4, 5]`.)

```js
function bubbleSort(arr) {
  let n = arr.length;
  for (let i = 0; i < n - 1; i++) {
    for (let j = 0; j < n - 1 - i; j++) {
      if (arr[j] > arr[j + 1]) {
        [arr[j], arr[j + 1]] = [arr[j + 1], arr[j]]; // swap using destructuring
      }
    }
  }
  return arr;
}
console.log(bubbleSort([5, 1, 4, 2])); // [1, 2, 4, 5]
```

A plain, unoptimized bubble sort is **O(n²)** in the worst case (input sorted in reverse order, requiring the maximum number of swaps) and also **O(n²)** in the average case (random order).

However, with a simple but important optimization — tracking whether *any* swap occurred during a pass, and stopping early if not — bubble sort's **best case** (the input is already sorted) improves to **O(n)**, since it only needs a single pass to confirm no swaps are needed.

```js
function bubbleSortOptimized(arr) {
  let n = arr.length;
  for (let i = 0; i < n - 1; i++) {
    let swapped = false;
    for (let j = 0; j < n - 1 - i; j++) {
      if (arr[j] > arr[j + 1]) {
        [arr[j], arr[j + 1]] = [arr[j + 1], arr[j]];
        swapped = true;
      }
    }
    if (!swapped) break; // already sorted — stop early
  }
  return arr;
}
```

Without this early-exit check, even an already-sorted array would still run through every planned pass doing no useful work, making the naive version O(n²) regardless of input order. This distinction — that an algorithm's complexity can differ across best, average, and worst cases, and that implementation details like an early exit can change which case applies — is a common, deeper follow-up in interviews about sorting.

A sorting algorithm is **stable** if it preserves the relative order of elements that are considered equal under the comparison being used. In other words, if two elements have the same sort key, a stable sort guarantees they stay in the same relative order they started in; an unstable sort makes no such guarantee and might reorder them.

Bubble sort, as typically implemented (only swapping when one element is *strictly greater than* its neighbor, never when they're equal), is a stable sorting algorithm, which is a nice side benefit of its simplicity — though its poor O(n²) performance is still why it's rarely used in real systems.

This matters in real applications whenever you sort by one property but want to preserve meaningful ordering from a previous sort on another property. For example:

```js
let orders = [
  { customer: "Alice", date: "2024-01-02" },
  { customer: "Bob",   date: "2024-01-01" },
  { customer: "Alice", date: "2024-01-01" }
];

// First, sort by date (chronological order)
orders.sort((a, b) => a.date.localeCompare(b.date));

// Then, stably sort by customer name
// A STABLE sort here keeps each customer's orders in the date order
// established by the previous sort; an unstable sort might shuffle them.
orders.sort((a, b) => a.customer.localeCompare(b.customer));
```

If the second sort were unstable, Alice's two orders could end up in the wrong relative order relative to each other, even though the final list is still correctly sorted by customer name overall. As a practical note, the ECMAScript specification has required `Array.prototype.sort()` to be stable since ES2019, so modern JavaScript engines guarantee stability for the built-in sort method.

